"use client";

/* ─────────────────────────────────────────────────────────
 * RATIO BALANCER: constrained multi-segment resource allocator
 *
 *   track      a single 1px thin line bar dividing 100% across
 *              segments; each segment expands or shrinks with
 *              flex-grow
 *   dividers   tactile thin line divider grips; delta-based drag
 *              ensures 1:1 finger tracking with zero initial
 *              jump on mobile and desktop
 *   numbers    percentage readouts roll in place via NumberRoll
 *              upon release; DOM text updates immediately while
 *              dragging
 *   touch      expanded 36px touch targets allow effortless finger
 *              dragging on phones
 *
 * Dividers are accessible separators with ArrowLeft/Right keys.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { NumberRoll } from "./number-roll";
import {
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import {
  normalizeRatios,
  type RatioSegment,
  useRatioBalancer,
} from "./use-ratio-balancer";

export type { RatioSegment };

export interface RatioBalancerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  label?: string;
  segments?: RatioSegment[];
  defaultSegments?: RatioSegment[];
  minRatio?: number;
  disabled?: boolean;
  onValueChange?: (ratios: number[]) => void;
  onValueCommit?: (ratios: number[]) => void;
}

const DEFAULT_SEGMENTS: RatioSegment[] = [
  { id: "inference", label: "Inference", ratio: 50 },
  { id: "training", label: "Training", ratio: 30 },
  { id: "cache", label: "Cache & KV", ratio: 20 },
];

const COLORS = [
  "bg-primary/10 text-primary border-primary/25",
  "bg-foreground/5 text-foreground border-foreground/15",
  "bg-muted text-muted-foreground border-border",
  "bg-accent text-accent-foreground border-border",
  "bg-primary/5 text-foreground border-primary/20",
];

export function RatioBalancer({
  label,
  segments: controlledSegments,
  defaultSegments = DEFAULT_SEGMENTS,
  minRatio = 5,
  disabled = false,
  onValueChange,
  onValueCommit,
  className = "",
  ...props
}: RatioBalancerProps) {
  const reduced = useInteractionReducedMotion();
  const [internalSegments, setInternalSegments] =
    React.useState<RatioSegment[]>(defaultSegments);
  const segments = controlledSegments ?? internalSegments;

  const currentRatios = React.useMemo(
    () => normalizeRatios(segments.map((s) => s.ratio)),
    [segments],
  );

  const handleChange = React.useCallback(
    (nextRatios: number[]) => {
      onValueChange?.(nextRatios);
    },
    [onValueChange],
  );

  const handleCommit = React.useCallback(
    (nextRatios: number[]) => {
      if (!controlledSegments) {
        setInternalSegments((prev) =>
          prev.map((seg, i) => ({
            ...seg,
            ratio: nextRatios[i] ?? seg.ratio,
          })),
        );
      }
      onValueCommit?.(nextRatios);
    },
    [controlledSegments, onValueCommit],
  );

  const balancer = useRatioBalancer({
    segments,
    minRatio,
    disabled,
    reduced,
    onChange: handleChange,
    onCommit: handleCommit,
  });

  return (
    <div
      {...props}
      role="region"
      aria-label={label ?? "Resource ratio balancer"}
      className={`relative flex w-full max-w-xl select-none flex-col text-foreground ${className}`}
    >
      {/* Label and Total */}
      {label && (
        <div className="mb-3 flex items-center justify-between text-[12px] font-medium text-muted-foreground">
          <span>{label}</span>
          <span className="font-mono text-[11px] tabular-nums text-muted-foreground/80">
            100% TOTAL
          </span>
        </div>
      )}

      {/* Main Bar Track (thin line borders only, zero heavy shadows) */}
      <div
        ref={(el) => balancer.attachTrack(el)}
        className="relative flex h-14 w-full overflow-hidden rounded-[14px] border border-border bg-surface p-1"
      >
        {segments.map((seg, i) => {
          const colorClass = COLORS[i % COLORS.length];
          const isLast = i === segments.length - 1;
          const ratio = currentRatios[i] ?? seg.ratio;

          return (
            <React.Fragment key={seg.id}>
              {/* Segment Cell */}
              <div
                ref={(el) => balancer.attachSegment(i, el)}
                className={`relative flex min-w-[42px] flex-col justify-between overflow-hidden rounded-[10px] border px-2.5 py-1.5 transition-[flex-grow] will-change-[flex-grow] ${colorClass}`}
                style={{ flexGrow: ratio }}
              >
                <div className="flex items-center justify-between">
                  <span className="truncate text-[11px] font-medium tracking-tight">
                    {seg.label}
                  </span>
                </div>

                <div className="flex items-baseline justify-between">
                  <span
                    ref={(el) => balancer.attachReadout(i, el)}
                    style={{
                      display:
                        balancer.activeDivider !== null ? "inline" : "none",
                    }}
                    className="font-mono text-[13px] font-medium tabular-nums"
                  >
                    {Math.round(ratio)}%
                  </span>
                  <span
                    style={{
                      display:
                        balancer.activeDivider !== null ? "none" : "inline",
                    }}
                    className="font-mono text-[13px] font-medium tabular-nums"
                  >
                    <NumberRoll
                      value={Math.round(ratio)}
                      suffix="%"
                      duration={380}
                    />
                  </span>
                </div>
              </div>

              {/* Divider Grip (Expanded 36px touch hit area for mobile fingers) */}
              {!isLast && (
                <div className="relative z-10 flex w-3 shrink-0 items-center justify-center">
                  <button
                    ref={(el) => balancer.attachDivider(i, el)}
                    {...balancer.getDividerProps(i)}
                    type="button"
                    role="separator"
                    disabled={disabled}
                    aria-orientation="vertical"
                    aria-label={`Adjust split between ${seg.label} and ${segments[i + 1]?.label}`}
                    style={{ touchAction: "none" }}
                    className={`group relative -inset-y-1 flex h-full w-3 cursor-ew-resize items-center justify-center touch-none select-none rounded before:absolute before:-inset-x-3.5 before:inset-y-0 before:content-[''] disabled:cursor-default disabled:opacity-40 ${INTERACTION_FOCUS}`}
                  >
                    <span className="h-6 w-0.5 rounded-full bg-border transition-colors group-hover:bg-primary group-focus-visible:bg-primary" />
                  </button>
                </div>
              )}
            </React.Fragment>
          );
        })}
      </div>

      {/* Legend & Breakdown */}
      <div className="mt-3 flex flex-wrap items-center justify-between gap-2 text-[11px] text-muted-foreground">
        <span className="flex items-center gap-1.5">
          <span className="size-1.5 rounded-full bg-primary" />
          <span>Drag dividers to reallocate percentages.</span>
        </span>
        <div className="flex items-center gap-3">
          {segments.map((seg) => (
            <span
              key={seg.id}
              className="flex items-center gap-1 font-mono text-[10px] tabular-nums"
            >
              <span>{seg.label}:</span>
              <span className="font-semibold text-foreground">
                {Math.round(currentRatios[segments.indexOf(seg)] ?? seg.ratio)}%
              </span>
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";
import { EASE_OUT } from "./imported-ui-interaction-motion";

export interface RatioSegment {
  id: string;
  label: string;
  ratio: number;
  color?: string;
}

type Options = {
  segments: RatioSegment[];
  minRatio?: number;
  disabled: boolean;
  reduced: boolean;
  onChange?: (ratios: number[]) => void;
  onCommit?: (ratios: number[]) => void;
};

/** Normalizes ratios to sum cleanly to 100. */
export function normalizeRatios(values: number[]): number[] {
  const sum = values.reduce((a, b) => a + b, 0);
  if (sum === 0) {
    const even = 100 / values.length;
    return values.map(() => Math.round(even));
  }
  let acc = 0;
  const result = values.map((v, i) => {
    if (i === values.length - 1) return Math.max(0, 100 - acc);
    const rounded = Math.round((v / sum) * 100);
    acc += rounded;
    return rounded;
  });
  return result;
}

export function useRatioBalancer(options: Options) {
  const trackRef = React.useRef<HTMLDivElement>(null);
  const segmentRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const readoutRefs = React.useRef<(HTMLSpanElement | null)[]>([]);
  const dividerRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const optionsRef = React.useRef(options);
  React.useLayoutEffect(() => {
    optionsRef.current = options;
  });

  const [activeDivider, setActiveDivider] = React.useState<number | null>(null);

  const gesture = React.useRef<{
    id: number;
    dividerIndex: number;
    startX: number;
    startRatios: number[];
    startRatioLeft: number;
    startRatioRight: number;
    currentRatios: number[];
    trackWidth: number;
  } | null>(null);

  const paint = React.useCallback((ratios: number[], animate: boolean) => {
    const o = optionsRef.current;
    ratios.forEach((ratio, i) => {
      const seg = segmentRefs.current[i];
      if (seg) {
        seg.style.transition =
          animate && !o.reduced ? `flex-grow 360ms ${EASE_OUT}` : "none";
        seg.style.flexGrow = String(ratio);
      }
      const readout = readoutRefs.current[i];
      if (readout) {
        readout.textContent = `${Math.round(ratio)}%`;
      }
    });

    // Update divider aria attributes
    let accumulated = 0;
    ratios.slice(0, -1).forEach((ratio, i) => {
      accumulated += ratio;
      const div = dividerRefs.current[i];
      if (div) {
        div.setAttribute("aria-valuenow", String(Math.round(accumulated)));
      }
    });
  }, []);

  const commit = React.useCallback(
    (next: number[], animate = true) => {
      const clean = normalizeRatios(next);
      paint(clean, animate);
      optionsRef.current.onChange?.(clean);
      optionsRef.current.onCommit?.(clean);
    },
    [paint],
  );

  const finish = React.useCallback(
    (cancelled: boolean) => {
      const g = gesture.current;
      if (!g) return;
      gesture.current = null;
      setActiveDivider(null);

      if (cancelled) {
        paint(g.startRatios, true);
        optionsRef.current.onChange?.(g.startRatios);
      } else {
        commit(g.currentRatios, false);
      }
    },
    [commit, paint],
  );

  React.useLayoutEffect(() => {
    if (!gesture.current) {
      const currentRatios = options.segments.map((s) => s.ratio);
      paint(currentRatios, true);
    }
  }, [options.segments, options.reduced, paint]);

  React.useEffect(() => {
    const interrupted = () => finish(true);
    const hidden = () => {
      if (document.hidden) interrupted();
    };
    window.addEventListener("blur", interrupted);
    document.addEventListener("visibilitychange", hidden);
    return () => {
      window.removeEventListener("blur", interrupted);
      document.removeEventListener("visibilitychange", hidden);
    };
  }, [finish]);

  const startDrag = React.useCallback(
    (dividerIndex: number, event: React.PointerEvent<HTMLButtonElement>) => {
      if (event.button !== 0 || !event.isPrimary || optionsRef.current.disabled)
        return;
      const track = trackRef.current;
      if (!track) return;

      const rect = track.getBoundingClientRect();
      event.currentTarget.setPointerCapture(event.pointerId);
      event.currentTarget.focus({ preventScroll: true });

      const currentRatios = optionsRef.current.segments.map((s) => s.ratio);

      gesture.current = {
        id: event.pointerId,
        dividerIndex,
        startX: event.clientX,
        startRatios: [...currentRatios],
        startRatioLeft: currentRatios[dividerIndex] ?? 50,
        startRatioRight: currentRatios[dividerIndex + 1] ?? 50,
        currentRatios: [...currentRatios],
        trackWidth: Math.max(1, rect.width),
      };

      setActiveDivider(dividerIndex);
      paint(currentRatios, false);
    },
    [paint],
  );

  const onPointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      const g = gesture.current;
      const o = optionsRef.current;
      if (!g || g.id !== event.pointerId) return;

      const idx = g.dividerIndex;
      const minRatio = o.minRatio ?? 5;

      // Delta-based calculation guarantees zero initial jump and 1:1 physical tracking
      const deltaX = event.clientX - g.startX;
      const deltaPercent = (deltaX / g.trackWidth) * 100;
      const pairTotal = g.startRatioLeft + g.startRatioRight;

      let newLeft = Math.round(g.startRatioLeft + deltaPercent);
      newLeft = Math.max(minRatio, Math.min(pairTotal - minRatio, newLeft));
      const newRight = pairTotal - newLeft;

      const next = [...g.currentRatios];
      next[idx] = newLeft;
      next[idx + 1] = newRight;

      if (
        next[idx] === g.currentRatios[idx] &&
        next[idx + 1] === g.currentRatios[idx + 1]
      )
        return;

      g.currentRatios = next;
      paint(next, false);
      o.onChange?.(next);
    },
    [paint],
  );

  const makeKeyHandler = React.useCallback(
    (dividerIndex: number) =>
      (event: React.KeyboardEvent<HTMLButtonElement>) => {
        if (event.key === "Escape") {
          event.preventDefault();
          finish(true);
          return;
        }

        if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key))
          return;
        event.preventDefault();

        const o = optionsRef.current;
        const delta =
          (event.shiftKey ? 5 : 1) * (event.key === "ArrowRight" ? 1 : -1);
        const minRatio = o.minRatio ?? 5;
        const segs = o.segments;

        const ratios = segs.map((s) => s.ratio);
        const combined = ratios[dividerIndex] + ratios[dividerIndex + 1];

        let newLeft = ratios[dividerIndex] + delta;
        newLeft = Math.max(minRatio, Math.min(combined - minRatio, newLeft));

        const next = [...ratios];
        next[dividerIndex] = newLeft;
        next[dividerIndex + 1] = combined - newLeft;

        commit(next);
      },
    [commit, finish],
  );

  const attachTrack = React.useCallback((el: HTMLDivElement | null) => {
    trackRef.current = el;
  }, []);
  const attachSegment = React.useCallback(
    (i: number, el: HTMLDivElement | null) => {
      segmentRefs.current[i] = el;
    },
    [],
  );
  const attachReadout = React.useCallback(
    (i: number, el: HTMLSpanElement | null) => {
      readoutRefs.current[i] = el;
    },
    [],
  );
  const attachDivider = React.useCallback(
    (i: number, el: HTMLButtonElement | null) => {
      dividerRefs.current[i] = el;
    },
    [],
  );

  const getDividerProps = React.useCallback(
    (idx: number) => ({
      onPointerDown: (e: React.PointerEvent<HTMLButtonElement>) =>
        startDrag(idx, e),
      onPointerMove,
      onPointerUp: (e: React.PointerEvent<HTMLButtonElement>) => {
        if (e.pointerId === gesture.current?.id) finish(false);
      },
      onPointerCancel: (e: React.PointerEvent<HTMLButtonElement>) => {
        if (e.pointerId === gesture.current?.id) finish(true);
      },
      onLostPointerCapture: (e: React.PointerEvent<HTMLButtonElement>) => {
        if (e.pointerId === gesture.current?.id) finish(true);
      },
      onBlur: () => finish(true),
      onKeyDown: makeKeyHandler(idx),
    }),
    [startDrag, onPointerMove, finish, makeKeyHandler],
  );

  return {
    attachTrack,
    attachSegment,
    attachReadout,
    attachDivider,
    activeDivider,
    commit,
    getDividerProps,
  };
}

